import{a0 as s,I as h,g as d,d as e,k as u,V as c,Y as _,j as p}from"./chunks/framework.CjoWWfVe.js";const q=JSON.parse('{"title":"Лицензия и конфиденциальность","description":"Договор-оферта и Политика обработки персональных данных ОмниКрафт ЕРП.","frontmatter":{"title":"Лицензия и конфиденциальность","description":"Договор-оферта и Политика обработки персональных данных ОмниКрафт ЕРП.","order":20,"eula_version":20260722,"eula_date":"2026-07-22"},"headers":[],"relativePath":"ru/docs/terms.md","filePath":"ru/docs/terms.md"}'),g={name:"ru/docs/terms.md"},f=Object.assign(g,{setup(m){const{frontmatter:l}=s(),t=r=>{if(!r)return"";const[a,i,o]=r.split("-"),n=["января","февраля","марта","апреля","мая","июня","июля","августа","сентября","октября","ноября","декабря"];return`${parseInt(o)} ${n[parseInt(i)-1]} ${a} года`};return(r,a)=>(h(),d("div",null,[a[0]||(a[0]=e("h1",{id:"⚖️-договор-оферта-пользовательское-соглашение-и-политика-обработки-персональных-данных",tabindex:"-1"},[u("⚖️ Договор-оферта (Пользовательское соглашение) и Политика обработки персональных данных "),e("a",{class:"header-anchor",href:"#⚖️-договор-оферта-пользовательское-соглашение-и-политика-обработки-персональных-данных","aria-label":'Permalink to "⚖️ Договор-оферта (Пользовательское соглашение) и Политика обработки персональных данных"'},"​")],-1)),e("p",null,[e("em",null,"Действующая редакция от "+c(t(_(l).eula_date)),1)]),a[1]||(a[1]=p('<p>Настоящий документ является официальным предложением (публичной офертой) и представляет собой единый договор-оферту между вами (далее — «Пользователь») и Разработчиком (далее — «Лицензиар») об использовании программы для ЭВМ «ОмниКрафт ЕРП» (далее — «Программа») и официального сайта.</p><p>Установка, копирование, загрузка, оплата или иное использование Программы означает безоговорочное согласие Пользователя со всеми условиями настоящего документа. Если вы не согласны с условиями, вы обязаны прекратить использование Программы и удалить её со своих устройств.</p><hr><h2 id="часть-1-лицензионныи-договор-оферта" tabindex="-1">ЧАСТЬ 1. ЛИЦЕНЗИОННЫЙ ДОГОВОР-ОФЕРТА <a class="header-anchor" href="#часть-1-лицензионныи-договор-оферта" aria-label="Permalink to &quot;ЧАСТЬ 1. ЛИЦЕНЗИОННЫЙ ДОГОВОР-ОФЕРТА&quot;">​</a></h2><h3 id="_1-1-предмет-соглашения-и-принцип-работы" tabindex="-1">1.1. Предмет соглашения и принцип работы <a class="header-anchor" href="#_1-1-предмет-соглашения-и-принцип-работы" aria-label="Permalink to &quot;1.1. Предмет соглашения и принцип работы&quot;">​</a></h3><p>Лицензиар предоставляет Пользователю персональное, неисключительное, непередаваемое право использования Программы в соответствии с её функциональным назначением на территории всего мира на весь срок действия исключительного права. Программа разработана на базе архитектуры с приоритетным локальным хранением данных (Local-First). Это означает, что Программа функционирует автономно на локальном устройстве Пользователя. Все пользовательские данные, включая базы данных, financial операции, списки клиентов и номенклатуру, создаются, обрабатываются и хранятся исключительно на локальном жестком диске Пользователя.</p><h3 id="_1-2-типы-лицензии-и-тарифы" tabindex="-1">1.2. Типы лицензий и тарифы <a class="header-anchor" href="#_1-2-типы-лицензии-и-тарифы" aria-label="Permalink to &quot;1.2. Типы лицензий и тарифы&quot;">​</a></h3><p>Программа предусматривает следующие уровни доступа:</p><ol><li><strong>Бесплатная (ознакомительная) версия:</strong> Предоставляется бесплатно без ограничения по времени. Включает полный функционал Программы с техническим ограничением: после проведения 20 (двадцати) операций продаж (чеков) Программа переходит в режим работы «только чтение» в части производственных и торговых операций.</li><li><strong>Лицензия «Standard» (подписочная или бессрочная):</strong> Активируется посредством уникального лицензионного ключа, приобретаемого Пользователем. Снимает ограничения на количество операций.</li><li><strong>Лицензия «PRO» (бессрочная):</strong> Приобретается как расширение для лицензии Standard. Открывает доступ к Мультипространствам и глобальной вкладке «Мой капитал».</li><li><strong>Специализированные модули:</strong> Приобретаются как единоразовые расширения под конкретное ремесло.</li></ol><p>Лицензионный ключ технически привязывается к уникальному коду оборудования (HWID) Пользователя. Одна коммерческая лицензия может быть привязана не более чем к 5 (пяти) устройствам Пользователя одновременно. Пользователь может самостоятельно редактировать и сбрасывать список привязанных устройств через форму управления лицензией на официальном сайте. Актуальные цены лицензий зафиксированы на странице <a href="/ru/docs/buy-license">Приобретение лицензии</a>.</p><h3 id="_1-3-ограничения-использования" tabindex="-1">1.3. Ограничения использования <a class="header-anchor" href="#_1-3-ограничения-использования" aria-label="Permalink to &quot;1.3. Ограничения использования&quot;">​</a></h3><p>Пользователю запрещается:</p><ul><li>Декомпилировать, дизассемблировать, модифицировать или пытаться извлечь исходный код Программы.</li><li>Сдавать Программу в аренду, продавать, сублицензировать или передавать лицензионные ключи активации третьим лицам.</li><li>Использовать Программу для совершения действий, противоречащих действующему законодательству.</li><li>Пытаться обойти технические ограничения ознакомительной версии любым способом.</li></ul><h3 id="_1-4-ограничение-ответственности-и-отказ-от-гарантии" tabindex="-1">1.4. Ограничение ответственности и отказ от гарантий <a class="header-anchor" href="#_1-4-ограничение-ответственности-и-отказ-от-гарантии" aria-label="Permalink to &quot;1.4. Ограничение ответственности и отказ от гарантий&quot;">​</a></h3><p><strong>Программа предоставляется на условиях «как есть». Лицензиар не предоставляет никаких явных или подразумеваемых гарантий того, что Программа будет отвечать требованиям Пользователя, будет работать непрерывно, без сбоев и ошибок.</strong></p><p>ПОЛЬЗОВАТЕЛЬ ПОНИМАЕТ И СОГЛАШАЕТСЯ, ЧТО ЛИЦЕНЗИАР НИ ПРИ КАКИХ ОБСТОЯТЕЛЬСТВАХ НЕ НЕСЕТ ОТВЕТСТВЕННОСТИ ЗА:</p><ol><li>Утерю, искажение или повреждение локальных баз данных Пользователя в результате сбоев питания, поломки жестких дисков, действия вирусов или некорректных действий Пользователя.</li><li>Любые прямые или косвенные убытки, упущенную выгоду или прерывание деловой активности, возникшие в результате использования или невозможности использования Программы.</li></ol><p><strong>Резервное копирование:</strong> Пользователь осознает, что вся ответственность за сохранность коммерческой информации лежит исключительно на нем. Пользователь обязуется самостоятельно и регулярно выполнять резервное копирование своих данных с использованием встроенных инструментов Программы на внешние носители или облачные хранилища.</p><h3 id="_1-5-возврат-и-отказ-от-покупки" tabindex="-1">1.5. Возврат и отказ от покупки <a class="header-anchor" href="#_1-5-возврат-и-отказ-от-покупки" aria-label="Permalink to &quot;1.5. Возврат и отказ от покупки&quot;">​</a></h3><ul><li><strong>Отказ до момента получения цифрового товара (до оказания услуги):</strong> Покупатель имеет право отказаться от покупки и вернуть денежные средства в любой момент до фактического получения (автоматической генерации и отправки на e-mail) лицензионного ключа активации.</li><li><strong>Пошаговый алгоритм действий для возврата средств:</strong><ol><li>Для оформления возврата Пользователь направляет заявление в свободной форме любым способом, указанным на странице <a href="/ru/docs/contacts">Контакты и реквизиты</a>. В обращении необходимо указать дату и время платежа, HWID, e-mail, указанный при покупке, и сумму.</li><li>Лицензиар обрабатывает обращение в течение <strong>3 рабочих дней</strong>.</li><li>После подтверждения возврат денежных средств осуществляется в полном объеме на ту же банковскую карту или счет, с которого производилась оплата.</li><li>Срок фактического поступления средств на счет Пользователя зависит от его банка-эмитента и обычно составляет <strong>от 1 до 5 рабочих дней</strong> (в редких случаях — до 30 дней в соответствии с правилами платежных систем).</li><li><strong>Важно:</strong> Возврат производится в полном объеме без удержания комиссий платежного сервиса или банка (Пользователь получает ровно ту сумму, которую оплатил).</li></ol></li><li><strong>Отказ после получения цифрового товара:</strong> Предоставление Пользователю неисключительного права на Программу считается полностью состоявшимся (услуга оказана) в момент автоматической генерации и отправки Пользователю уникального лицензионного ключа активации на его e-mail. В соответствии с законодательством РФ, возврат денежных средств за цифровой продукт надлежащего качества после его передачи Пользователю не производится. Перед приобретением коммерческой лицензии Пользователю предоставляется бесплатная ознакомительная версия Программы без ограничения по времени для полной оценки ее характеристик и потребительских свойств. В случае возникновения любых технических проблем с активацией ключа или стабильностью работы Программы, Лицензиар обязуется оперативно устранить проблему или произвести замену ключа.</li></ul><hr><h2 id="часть-2-политика-обработки-персональных-данных-политика-конфиденциальности" tabindex="-1">ЧАСТЬ 2. ПОЛИТИКА ОБРАБОТКИ ПЕРСОНАЛЬНЫХ ДАННЫХ (ПОЛИТИКА КОНФИДЕНЦИАЛЬНОСТИ) <a class="header-anchor" href="#часть-2-политика-обработки-персональных-данных-политика-конфиденциальности" aria-label="Permalink to &quot;ЧАСТЬ 2. ПОЛИТИКА ОБРАБОТКИ ПЕРСОНАЛЬНЫХ ДАННЫХ (ПОЛИТИКА КОНФИДЕНЦИАЛЬНОСТИ)&quot;">​</a></h2><h3 id="_2-1-отсутствие-сбора-данных-локальных-проектов" tabindex="-1">2.1. Отсутствие сбора данных локальных проектов <a class="header-anchor" href="#_2-1-отсутствие-сбора-данных-локальных-проектов" aria-label="Permalink to &quot;2.1. Отсутствие сбора данных локальных проектов&quot;">​</a></h3><p>В связи с архитектурой локального хранения данных (Local-First), Лицензиар не имеет доступа к базам данных Пользователя. Лицензиар не собирает, не обрабатывает и не хранит персональные данные клиентов Пользователя, списки поставщиков, коммерческую тайну, информацию о доходах, остатках на счетах и иную пользовательскую информацию. Лицензиар не является оператором персональных данных (в терминологии Федерального закона № 152-ФЗ «О персональных данных») применительно к информации, вносимой Пользователем в локальную базу данных Программы.</p><h3 id="_2-2-автоматически-собираемая-техническая-информация-телеметрия" tabindex="-1">2.2. Автоматически собираемая техническая информация (Телеметрия) <a class="header-anchor" href="#_2-2-автоматически-собираемая-техническая-информация-телеметрия" aria-label="Permalink to &quot;2.2. Автоматически собираемая техническая информация (Телеметрия)&quot;">​</a></h3><p>Для обеспечения работы системы лицензирования и улучшения качества Программы, Лицензиар может собирать исключительно обезличенную техническую информацию:</p><ul><li><strong>Уникальный код оборудования (HWID):</strong> Обезличенный криптографический хэш параметров оборудования. Он используется исключительно для проверки привязки лицензионного ключа и защиты от пиратства. Данный код не позволяет идентифицировать конкретное физическое лицо.</li><li><strong>Технические метрики:</strong> Язык интерфейса, версия операционной системы, версия Программы и счетчик проведенных операций (для контроля лимита бесплатной версии).</li><li><strong>Отчеты о сбоях:</strong> В случае критической ошибки Программа отправляет технический отчет о последовательности вызовов (трассировку стека). Программа автоматически вырезает персональные пути локальных папок компьютера, заменяя их на обезличенные маски, чтобы исключить передачу имени учетной записи операционной системы.</li></ul><h3 id="_2-3-обработка-персональных-данных-при-оформлении-платежа" tabindex="-1">2.3. Обработка персональных данных при оформлении платежа <a class="header-anchor" href="#_2-3-обработка-персональных-данных-при-оформлении-платежа" aria-label="Permalink to &quot;2.3. Обработка персональных данных при оформлении платежа&quot;">​</a></h3><ul><li>При оформлении и оплате лицензии через авторизованный платежный шлюз (интернет-эквайринг), Пользователь указывает адрес электронной почты (e-mail) и HWID устройства.</li><li>Предоставляя данные, Пользователь выражает свое согласие на обработку этой информации Лицензиаром исключительно в целях автоматической генерации, доставки и технического сопровождения лицензионного токена.</li><li><strong>В целях обеспечения конфиденциальности и минимизации собираемых данных, адрес электронной почты (e-mail) используется Лицензиаром исключительно для отправки сообщения с токеном лицензии непосредственно в момент совершения транзакции и не сохраняется (не хранится) в базах данных на серверах Лицензиара.</strong> В базах данных Лицензиара сохраняется только анонимизированный лицензионный токен и хэш-отпечаток устройства.</li><li>Сбор и обработка этих данных осуществляются с соблюдением всех необходимых мер информационной безопасности. Данные не передаются третьим лицам ни при каких обстоятельствах (за исключением законных требований ведомств РФ).</li></ul><h3 id="_2-4-управление-согласием-отказ-от-сбора" tabindex="-1">2.4. Управление согласием (Отказ от сбора) <a class="header-anchor" href="#_2-4-управление-согласием-отказ-от-сбора" aria-label="Permalink to &quot;2.4. Управление согласием (Отказ от сбора)&quot;">​</a></h3><p>Пользователь имеет полное право в любой момент отозвать свое согласие на передачу аналитической информации и отчетов об ошибках. Для этого достаточно снять соответствующую отметку в разделе «Настройки программы» (Глобальные настройки). При отключении данного параметра Программа переходит в полностью автономный режим (за исключением разовых автоматических запросов к серверу при активации лицензионного ключа).</p><h3 id="_2-5-использование-веб-ресурсов" tabindex="-1">2.5. Использование веб-ресурсов <a class="header-anchor" href="#_2-5-использование-веб-ресурсов" aria-label="Permalink to &quot;2.5. Использование веб-ресурсов&quot;">​</a></h3><p>При посещении сайта <code>omnicraft-erp.com</code> или обращении к официальным серверам биллинга Лицензиара (включая домен <code>nmurashkin.ru</code>) веб-сервер может автоматически собирать стандартные журналы подключений (сетевой адрес устройства, тип браузера, время доступа) исключительно в целях обеспечения сетевой безопасности и защиты от сетевых атак. Сайт не использует рекламные или отслеживающие сторонние файлы «куки».</p><h3 id="_2-6-использование-локального-и-сессионного-хранилища-браузера-sessionstorage" tabindex="-1">2.6. Использование локального и сессионного хранилища браузера (sessionStorage) <a class="header-anchor" href="#_2-6-использование-локального-и-сессионного-хранилища-браузера-sessionstorage" aria-label="Permalink to &quot;2.6. Использование локального и сессионного хранилища браузера (sessionStorage)&quot;">​</a></h3><p>Сайт использует локальное сессионное хранилище браузера (<code>sessionStorage</code>) исключительно для поддержания технической работоспособности личного кабинета и сохранения статуса авторизации в рамках активной сессии пользователя. Хранение данных осуществляется локально на устройстве пользователя. Внесенные данные не используются для отслеживания или маркетинга и автоматически удаляются браузером при закрытии вкладки или окна браузера.</p><hr><h2 id="payment-delivery-returns" tabindex="-1">ЧАСТЬ 3. ПРАВИЛА ОПЛАТЫ, ДОСТАВКИ И ВОЗВРАТА СРЕДСТВ <a class="header-anchor" href="#payment-delivery-returns" aria-label="Permalink to &quot;ЧАСТЬ 3. ПРАВИЛА ОПЛАТЫ, ДОСТАВКИ И ВОЗВРАТА СРЕДСТВ {#payment-delivery-returns}&quot;">​</a></h2><h3 id="_3-1-описание-товара-и-потребительские-своиства" tabindex="-1">3.1. Описание товара и потребительские свойства <a class="header-anchor" href="#_3-1-описание-товара-и-потребительские-своиства" aria-label="Permalink to &quot;3.1. Описание товара и потребительские свойства&quot;">​</a></h3><p>Товаром является неисключительное право использования программы для ЭВМ (цифровой лицензионный ключ). Потребительские свойства: активация лицензионного ключа в программе ОмниКрафт ЕРП снимает базовое техническое ограничение бесплатной версии (лимит в 20 чеков) и, в зависимости от выбранного тарифа, предоставляет доступ к расширенным функциям (безлимитные продажи, Мультипространства, модуль «Мой капитал»). Товар поставляется исключительно в цифровом (электронном) виде.</p><h3 id="_3-2-способы-и-условия-оплаты" tabindex="-1">3.2. Способы и условия оплаты <a class="header-anchor" href="#_3-2-способы-и-условия-оплаты" aria-label="Permalink to &quot;3.2. Способы и условия оплаты&quot;">​</a></h3><p>Оплата осуществляется онлайн через авторизованный платежный шлюз (интернет-эквайринг), полностью отвечающий международным стандартам безопасности (PCI DSS). К оплате принимаются:</p><ul><li>Банковские карты (МИР, Visa, Mastercard, UnionPay).</li><li>Система быстрых платежей (СБП).</li><li>Yandex Pay и другие доступные электронные методы. Все передаваемые данные зашифрованы по надежному протоколу SSL, что гарантирует абсолютную безопасность ваших платежных реквизитов.</li></ul><h3 id="_3-3-порядок-и-сроки-доставки-оказание-услуг" tabindex="-1">3.3. Порядок и сроки доставки (Оказание услуг) <a class="header-anchor" href="#_3-3-порядок-и-сроки-доставки-оказание-услуг" aria-label="Permalink to &quot;3.3. Порядок и сроки доставки (Оказание услуг)&quot;">​</a></h3><ul><li>Доставка цифрового товара осуществляется в автоматическом или ручном режиме путем отправки электронного письма на e-mail, указанный Покупателем при оплате.</li><li>Срок исполнения: автоматическая генерация и отправка ключа занимает от 1 до 5 минут с момента успешной оплаты. В период настройки автоматического биллинга, при проведении платежа в ручном режиме, лицензионный ключ отправляется в течение 24 часов с момента подтверждения оплаты.</li></ul><h3 id="_3-4-возврат-и-отказ-от-покупки" tabindex="-1">3.4. Возврат и отказ от покупки <a class="header-anchor" href="#_3-4-возврат-и-отказ-от-покупки" aria-label="Permalink to &quot;3.4. Возврат и отказ от покупки&quot;">​</a></h3><ul><li><strong>Отказ до момента получения цифрового товара (до оказания услуги):</strong> Покупатель имеет право отказаться от заказа и вернуть денежные средства в любой момент до фактического получения (автоматической генерации и отправки на e-mail) лицензионного ключа активации.</li><li><strong>Пошаговый алгоритм действий для возврата средств:</strong><ol><li>Для оформления возврата Пользователь направляет заявление в свободной форме любым способом, указанным на странице <a href="/ru/docs/contacts">Контакты и реквизиты</a>. В обращении необходимо указать дату и время платежа, HWID, e-mail, указанный при покупке, и сумму.</li><li>Лицензиар обрабатывает обращение в течение <strong>3 рабочих дней</strong>.</li><li>После подтверждения возврат денежных средств осуществляется в полном объеме на ту же банковскую карту или счет, с которого производилась оплата.</li><li>Срок фактического поступления средств на счет Пользователя зависит от его банка-эмитента и обычно составляет от 1 до 5 рабочих дней.</li><li><strong>Важно:</strong> Возврат производится в полном объеме без удержания комиссий платежного сервиса или банка (Пользователь получает ровно ту сумму, которую оплатил).</li></ol></li><li><strong>Отказ после получения цифрового товара:</strong> Предоставление Пользователю неисключительного права на Программу считается полностью состоявшимся (услуга оказана) в момент автоматической генерации и отправки Пользователю уникального лицензионного ключа активации на его e-mail. В соответствии с законодательством РФ, возврат денежных средств за цифровой продукт надлежащего качества после его передачи Пользователю не производится. Перед приобретением коммерческой лицензии Пользователю предоставляется бесплатная ознакомительная версия Программы без ограничения по времени для полной оценки ее характеристик и потребительских свойств. В случае возникновения любых технических проблем с активацией ключа или стабильностью работы Программы, Лицензиар обязуется оперативно устранить проблему или произвести замену ключа.</li></ul><h2 id="часть-4-заключительные-положения-и-реквизиты" tabindex="-1">ЧАСТЬ 4. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ И РЕКВИЗИТЫ <a class="header-anchor" href="#часть-4-заключительные-положения-и-реквизиты" aria-label="Permalink to &quot;ЧАСТЬ 4. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ И РЕКВИЗИТЫ&quot;">​</a></h2><h3 id="_4-1-применимое-право-и-разрешение-споров" tabindex="-1">4.1. Применимое право и разрешение споров <a class="header-anchor" href="#_4-1-применимое-право-и-разрешение-споров" aria-label="Permalink to &quot;4.1. Применимое право и разрешение споров&quot;">​</a></h3><p>Настоящее Соглашение регулируется и толкуется в соответствии с действующим законодательством Российской Федерации. Все споры и разногласия подлежат обязательному досудебному претензионному урегулированию. Срок рассмотрения письменной претензии составляет 30 (тридцать) календарных дней с момента ее получения. При невозможности урегулирования спора в досудебном порядке, он подлежит рассмотрению в суде по месту нахождения Лицензиара.</p><h3 id="_4-2-обстоятельства-непреодолимои-силы-форс-мажор" tabindex="-1">4.2. Обстоятельства непреодолимой силы (Форс-мажор) <a class="header-anchor" href="#_4-2-обстоятельства-непреодолимои-силы-форс-мажор" aria-label="Permalink to &quot;4.2. Обстоятельства непреодолимой силы (Форс-мажор)&quot;">​</a></h3><p>Стороны освобождаются от ответственности за частичное или полное неисполнение обязательств по настоящему Соглашению, если оно явилось следствием обстоятельств непреодолимой силы. К таким обстоятельствам относятся чрезвычайные и непредотвратимые события, включая военные действия, стихийные бедствия, решения государственных органов, масштабные аварии в работе сети Интернет, сбои серверов или облачных провайдеров, а также тяжелая внезапная болезнь либо экстренная госпитализация Лицензиара, объективно препятствующая исполнению обязательств в установленный срок.</p><h3 id="_4-3-изменение-условии" tabindex="-1">4.3. Изменение условий <a class="header-anchor" href="#_4-3-изменение-условии" aria-label="Permalink to &quot;4.3. Изменение условий&quot;">​</a></h3><p>Лицензиар оставляет за собой право в одностороннем порядке вносить изменения в настоящее Соглашение. Новая редакция вступает в силу с момента ее публикации на официальном сайте Программы. В случае несогласия Пользователя с изменениями Соглашения, Пользователь обязан незамедлительно прекратить любое использование Программы и удалить её со своих устройств.</p><h3 id="_4-4-превалирование-языка" tabindex="-1">4.4. Превалирование языка <a class="header-anchor" href="#_4-4-превалирование-языка" aria-label="Permalink to &quot;4.4. Превалирование языка&quot;">​</a></h3><p>Настоящее Соглашение может быть переведено на другие языки для удобства Пользователей. В случае любых разночтений, расхождений или противоречий между версией Соглашения на русском языке и версией на любом другом языке, преимущественную (превалирующую) и окончательную юридическую силу всегда имеет версия на русском языке.</p><h3 id="_4-5-реквизиты-разработчика-лицензиара" tabindex="-1">4.5. Реквизиты Разработчика (Лицензиара) <a class="header-anchor" href="#_4-5-реквизиты-разработчика-лицензиара" aria-label="Permalink to &quot;4.5. Реквизиты Разработчика (Лицензиара)&quot;">​</a></h3><p>Правообладателем и Разработчиком Программы является: <strong>Физическое лицо Мурашкин Николай Валерьевич</strong>, применяющее специальный налоговый режим «Налог на профессиональный доход» (самозанятый). Подробная информация о разработчике, его мастерской и философии проекта доступна в разделе <a href="/ru/docs/about">О разработчиках</a>.</p><ul><li><strong>ИНН:</strong> 232904256501</li><li><strong>Контакты для официальных обращений:</strong> См. страницу <a href="/ru/docs/contacts">Контакты</a></li></ul>',58))]))}});export{q as __pageData,f as default};
